  function renderQa(){var refs=docs.slice(0,4).map(function(item,i){return '<article class="reference-item"><strong title="'+escapeHtml(item.name)+'">'+(i+1)+'. '+escapeHtml(item.name)+'</strong><footer><span>'+item.size+' · 2026-03-30</span><div><button class="page-icon-button" data-toast="引用文件下载完成" aria-label="下载">'+icon("download",17)+'</button><button class="page-icon-button share-action" data-file="'+escapeHtml(item.name)+'" aria-label="分享">'+icon("share",17)+'</button><button class="page-icon-button" data-toast="已收藏引用文件" aria-label="收藏">'+icon("star",17)+'</button></div></footer></article>'}).join("");root.innerHTML='<section class="suite-page">'+searchModes("qa",'<button class="btn" type="button" data-history-open aria-controls="searchHistoryPanel" aria-expanded="false">'+icon("history",17)+' 历史记录</button><button class="btn btn-primary" data-nav="qa-result.html">'+icon("plus",17)+' 新建会话</button>')+'<div class="qa-main" data-context-layout><section class="qa-answer"><div class="qa-question"><div class="question-bubble">这张报销单有什么问题？为什么被退回了？</div></div><article class="robot-answer"><h2>一、报销单存在的主要问题</h2><h3>1. 缺少审批签字</h3><p>报销单的“部门负责人”和“财务审核”栏均未签字，审批流程未完成。</p><h3>2. 发票金额与报销金额不一致</h3><p>发票合计金额为 ¥1,280.00，报销金额填写为 ¥1,300.00。</p><h3>3. 出差信息填写不完整</h3><p>缺少出差时间及目的地，无法核实出差必要性。</p><h2>二、驳回原因总结</h2><p>审批流程未完成、金额不一致、附件缺失及涂改不规范，故被退回。</p><h2>三、建议修改措施</h2><ul><li>补全审批签字，确保流程合规；</li><li>核对并统一发票金额和报销金额；</li><li>补充完整票据及行程单。</li></ul></article><div class="answer-composer"><textarea id="qaInput" placeholder="描述你的需求，AI帮你查知识、写材料、生成内容……"></textarea><div class="composer-footer"><select class="form-control" style="width:150px"><option>全范围知识库</option></select><button class="send-circle" data-qa-send aria-label="发送">'+icon("send",18)+'</button></div></div></section><aside class="reference-list" data-reference-panel><h2>相关引用</h2>'+refs+'</aside>'+searchHistoryPanel()+'</div></section>'}
