  function renderQaEnhanced(){var restricted=[{name:'国网物资有限公司差旅费管理实施细则（2026版）.pdf',size:'1.6 MB',place:'公司知识库 / 财务制度'},{name:'财务共享中心报销审核操作口径（内部）.docx',size:'860 KB',place:'财务资产部 / 内部工作指引'}],refs=docs.slice(0,4).map(function(item,index){return qaReferenceItem(item,index+1,false)}).join('')+restricted.map(function(item,index){return qaReferenceItem(item,index+5,true)}).join('');root.innerHTML='<section class="suite-page qa-page">'+searchModes('qa','<button class="btn" type="button" data-history-open aria-controls="searchHistoryPanel" aria-expanded="false">'+icon('history',17)+' 历史记录</button><button class="btn btn-primary" data-nav="qa-result.html">'+icon('plus',17)+' 新建会话</button>')+'<div class="qa-main" data-context-layout><section class="qa-answer"><div class="qa-conversation" id="qaConversation" tabindex="0" aria-label="问答内容，可滚动查看"><div class="qa-question">'+qaReceiptPreview()+'<div class="question-bubble">请帮我检查这张报销单有什么问题，为什么被退回？</div></div><article class="robot-answer"><header class="answer-heading"><span class="answer-avatar">'+icon('bot',19)+'</span><div><strong>AI 智能问答</strong><small>已结合 6 份相关知识进行分析</small></div></header><p>从您上传的报销单来看，本次退回并非单一字段错误，而是审批、金额、行程附件和票据规范四类问题共同导致。以下结论已按现行制度与操作口径交叉核验。</p><h2>一、报销单存在的主要问题</h2><h3>1. 审批链未完成</h3><p>“部门负责人”和“财务审核”栏均未签字，系统无法确认业务真实性与预算责任。差旅费报销应先完成部门负责人审批，再进入财务共享审核。'+qaCitation(1)+qaCitation(5)+'</p><h3>2. 发票金额与申请金额不一致</h3><p>附件发票合计金额为 ¥1,280.00，报销单申请金额为 ¥1,300.00，存在 ¥20.00 差额。未提供差额说明时，系统会按金额校验不通过处理。'+qaCitation(2)+qaCitation(6)+'</p><h3>3. 出差信息填写不完整</h3><p>报销单未填写完整的出差起止时间、目的地和出差事由，无法与行程及住宿票据建立对应关系。'+qaCitation(3)+'</p><h3>4. 必要附件缺失</h3><p>当前材料中未发现出差审批单、行程单及住宿明细。涉及交通与住宿费用时，应提供能够证明日期、地点和金额的完整附件。'+qaCitation(2)+qaCitation(4)+'</p><h3>5. 手工涂改缺少说明</h3><p>费用明细中的交通费金额存在手工修改痕迹，但修改处没有经办人签字或情况说明，无法满足票据留痕要求。'+qaCitation(6)+'</p><h2>二、退回原因总结</h2><p>本次报销单同时触发了“审批未完成”“申请金额不一致”“行程信息不完整”“附件缺失”和“涂改无说明”五项校验，因此财务共享中心将单据退回补正。</p><h2>三、建议修改步骤</h2><ol><li>核对发票原件，将报销金额统一调整为 ¥1,280.00；如 ¥20.00 确需报销，补充对应合规票据和书面说明。</li><li>补充出差日期、目的地、事由，并上传出差审批单、交通行程单和住宿明细。</li><li>对涂改处重新填制或附情况说明，由经办人签字确认。</li><li>重新提交部门负责人审批，审批完成后再进入财务审核。</li></ol><div class="permission-notice">'+icon('lock',18)+'<div><strong>部分依据暂不可查看</strong><p>当前问答所需部分文档您暂无查看权限，可发起对应文档的访问权限申请。'+qaCitation(5)+qaCitation(6)+'</p></div></div></article></div><div class="answer-composer"><div class="composer-attachments" data-qa-attachment-list hidden></div><textarea id="qaInput" placeholder="继续提问，或添加文件、图片作为补充材料……"></textarea><div class="composer-footer"><div class="composer-left"><select class="form-control" aria-label="知识库范围"><option>全范围知识库</option><option>公司知识库</option><option>部门知识库</option><option>我的知识库</option></select><button class="composer-tool composer-tool-icon" type="button" title="添加文件" aria-label="添加文件" data-qa-pick-file>'+icon('paperclip',18)+'</button><button class="composer-tool composer-tool-icon" type="button" title="添加图片" aria-label="添加图片" data-qa-pick-image>'+icon('image',18)+'</button></div><button class="send-circle" data-qa-send aria-label="发送">'+icon('send',18)+'</button></div><input class="visually-hidden" type="file" data-qa-file-input multiple accept=".doc,.docx,.pdf,.xls,.xlsx,.ppt,.pptx,.txt"><input class="visually-hidden" type="file" data-qa-image-input multiple accept="image/*"></div></section><aside class="reference-list" data-reference-panel aria-label="相关引用文件"><header><h2>相关引用</h2><span>6 份</span></header><div class="reference-scroll">'+refs+'</div></aside>'+searchHistoryPanel()+'</div></section>'}
